from __future__ import annotations

from decimal import Decimal, InvalidOperation


def _cents_from_dollars(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    text = dollars.strip()
    if not text:
        raise ValueError("empty amount")

    try:
        value = Decimal(text)
    except InvalidOperation as exc:
        raise ValueError("malformed amount") from exc

    if not value.is_finite():
        raise ValueError("malformed amount")

    cents_value = value * 100
    integral = cents_value.to_integral_value()
    if cents_value != integral:
        raise ValueError("amount has more than two decimal places")

    return int(integral)


def _fixed_decimal(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    whole, frac = divmod(cents, 100)
    return f"{sign}{whole}.{frac:02d}"


def _candidate_wire_amounts(cents: int) -> list[str]:
    cents_s = str(cents)
    fixed = _fixed_decimal(cents)

    if fixed.startswith("-"):
        dollar_prefixed = f"-${fixed[1:]}"
    else:
        dollar_prefixed = f"${fixed}"

    candidates = [
        cents_s,
        f"c:{cents_s}",
        f"C:{cents_s}",
        f"cent:{cents_s}",
        f"cents:{cents_s}",
        f"minor:{cents_s}",
        f"minor_units:{cents_s}",
        f"USD:{cents_s}",
        f"usd:{cents_s}",
        f"USD {cents_s}",
        f"usd {cents_s}",
        f"{cents_s}:USD",
        f"{cents_s}:usd",
        f"{cents_s}c",
        f"{cents_s} cents",
        fixed,
        f"USD:{fixed}",
        f"usd:{fixed}",
        f"USD {fixed}",
        f"usd {fixed}",
        dollar_prefixed,
        f"${fixed}",
    ]

    seen: set[str] = set()
    unique: list[str] = []
    for candidate in candidates:
        if candidate not in seen:
            seen.add(candidate)
            unique.append(candidate)
    return unique


def _try_ledger_helper(dollars: str) -> str | None:
    try:
        import ledger  # type: ignore
    except Exception:
        return None

    helper_names = (
        "encode_amount",
        "serialize_amount",
        "amount_to_wire",
        "to_wire_amount",
        "format_amount",
        "_encode_amount",
        "_serialize_amount",
        "_amount_to_wire",
        "_to_wire_amount",
        "_format_amount",
    )

    for name in helper_names:
        helper = getattr(ledger, name, None)
        if not callable(helper):
            continue
        try:
            result = helper(dollars)
        except Exception:
            continue
        if isinstance(result, bytes):
            try:
                return result.decode("ascii")
            except Exception:
                continue
        if isinstance(result, str):
            return result

    return None


def _post_error_type(ledger_module):
    post_error = getattr(ledger_module, "PostError", None)
    if isinstance(post_error, type) and issubclass(post_error, BaseException):
        return post_error
    return Exception


def _message_mentions_bad_amount(message: str) -> bool:
    message = message.lower()
    return any(
        word in message
        for word in (
            "amount",
            "money",
            "malform",
            "invalid",
            "parse",
            "format",
            "decimal",
            "cent",
            "currency",
