        return None
    else:
        return None

    if not _message_mentions_bad_amount(probe_message):
        return None
    if _message_mentions_unknown_account(probe_message):
        return None

    for candidate in candidates:
        try:
            post(account, candidate, memo="encode_amount probe")
        except post_error as exc:
            message = str(exc)
            if _message_mentions_unknown_account(message) and not _message_mentions_bad_amount(message):
                return candidate
        except Exception:
            continue
        else:
            return candidate

    return None


