import re

_AMOUNT_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d{1,2})?|\.\d{1,2})$")


def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not _AMOUNT_RE.fullmatch(s):
        raise ValueError(f"malformed dollar amount: {dollars!r}")

    sign = -1 if s.startswith("-") else 1
    if s[:1] in "+-":
        s = s[1:]

    whole, dot, frac = s.partition(".")
    whole_cents = int(whole or "0") * 100
    frac_cents = int((frac + "00")[:2]) if dot else 0

    cents = whole_cents + frac_cents
    if cents == 0:
        return "0"
    return str(sign * cents)

